function draw() {
  // Draw starfield background
  ctx.fillStyle = '#000010';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  // small twinkling stars
  stars.forEach(star => {
    ctx.fillStyle = 'white';
    ctx.globalAlpha = star.brightness;
    ctx.fillRect(star.x, star.y, 2, 2);
    // simple twinkle
    star.brightness += (Math.random() - 0.5) * 0.05;
    star.brightness = Math.min(1, Math.max(0.3, star.brightness));
  });
  ctx.globalAlpha = 1;

  // ship as triangle
  ctx.fillStyle = shield ? '#00ffff' : '#ffffff';
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y + ship.height);
  ctx.lineTo(ship.x + ship.width / 2, ship.y);
  ctx.lineTo(ship.x + ship.width, ship.y + ship.height);
  ctx.closePath();
  ctx.fill();

  // asteroids with radial gradient
  asteroids.forEach(a => {
    const grad = ctx.createRadialGradient(
      a.x + a.size / 2,
      a.y + a.size / 2,
      a.size * 0.1,
      a.x + a.size / 2,
      a.y + a.size / 2,
      a.size / 2
    );
    grad.addColorStop(0, '#777777');
    grad.addColorStop(1, '#222222');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(a.x + a.size / 2, a.y + a.size / 2, a.size / 2, 0, Math.PI * 2);
    ctx.fill();
  });

  // power‑ups as rotating shield icons
  powerUps.forEach(p => {
    ctx.save();
    ctx.translate(p.x + p.size / 2, p.y + p.size / 2);
    ctx.rotate((Date.now() % 2000) / 2000 * Math.PI * 2);
    ctx.fillStyle = 'gold';
    ctx.beginPath();
    ctx.arc(0, 0, p.size / 2, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  });

  // Game over overlay
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'red';
    ctx.font = '48px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

